function compose(f, g) {
  return function (x) {
    return f(g(x));
  };
}

function addOne(x) {
  return x + 1;
}

function twice(x) {
  return x * 2;
}

var addThenDouble = compose(twice, addOne);
var doubleThenAdd = compose(addOne, twice);
console.log(addThenDouble(5));
console.log(doubleThenAdd(5));
